<!DOCTYPE html><html lang="<?= htmlspecialchars($_SESSION['lang'], ENT_QUOTES, 'UTF-8') ?>"><head><meta charset="UTF-8"><link rel="icon" type="image/svg+xml" href="image/favicon.svg"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title><?= htmlspecialchars($lang['employerforgetpassword_title'] ?? 'Employer password recovery', ENT_QUOTES, 'UTF-8') ?></title><style>
:root{--red:#b42318;--muted:#667085;--line:#e4e7ec}*{box-sizing:border-box}body{margin:0;min-height:100vh;display:grid;place-items:center;padding:20px;background:linear-gradient(135deg,#fff4f2,#f4f7fb);font-family:Arial,sans-serif;color:#202124}.shell{width:min(100%,440px);padding:28px;border:1px solid var(--line);border-radius:16px;background:#fff;box-shadow:0 18px 55px rgba(16,24,40,.12);text-align:center}.shell h1{margin:0 0 8px;color:var(--red);font-size:24px}.shell p,.modal-card p{color:var(--muted);line-height:1.5}.backdrop[hidden]{display:none}.backdrop{position:fixed;inset:0;z-index:10;display:grid;place-items:center;padding:18px;background:rgba(16,24,40,.58)}.modal-card{position:relative;width:min(100%,430px);padding:30px;border-radius:16px;background:#fff;box-shadow:0 24px 70px rgba(16,24,40,.25)}.modal-card h2{margin:0 36px 8px 0;color:var(--red);font-size:22px}.close{position:absolute;top:12px;right:14px;border:0;background:transparent;color:#667085;font-size:28px;cursor:pointer}label{display:block;margin:16px 0 7px;font-weight:700}input{width:100%;padding:12px 13px;border:1px solid var(--line);border-radius:8px;font-size:16px}.otp{text-align:center;letter-spacing:9px;font-size:24px;font-weight:700}.primary,.resend{width:100%;margin-top:18px;padding:12px;border:0;border-radius:8px;font-weight:700;cursor:pointer}.primary{color:#fff;background:var(--red)}.resend{margin-top:10px;color:var(--red);background:#fff4f2}.primary:disabled,.resend:disabled{opacity:.55;cursor:wait}.message{min-height:21px;margin:14px 0 0!important;color:var(--red)!important;font-size:14px}.password-wrap{position:relative}.password-wrap input{padding-right:45px}.eye{position:absolute;right:7px;top:50%;width:34px;height:34px;transform:translateY(-50%);border:0;background:transparent;color:#667085;cursor:pointer;font-size:18px}
</style></head><body><main class="shell"><h1><?= htmlspecialchars($lang['employerforgetpassword_title'] ?? 'Employer password recovery', ENT_QUOTES, 'UTF-8') ?></h1><p><?= htmlspecialchars($lang['otp_instruction'] ?? 'Enter the 5-digit code sent to your email.', ENT_QUOTES, 'UTF-8') ?></p></main>
<div class="backdrop" id="otp-modal" <?= $isVerified?'hidden':'' ?>><section class="modal-card" role="dialog" aria-modal="true"><button class="close" type="button" data-close>&times;</button><h2><?= htmlspecialchars($lang['otp_title'] ?? 'Verify your email', ENT_QUOTES, 'UTF-8') ?></h2><p><?= htmlspecialchars($lang['otp_instruction'] ?? 'Enter the 5-digit code sent to your email.', ENT_QUOTES, 'UTF-8') ?></p><form id="otp-form"><label for="otp-code"><?= htmlspecialchars($lang['otp_label'] ?? 'Verification code', ENT_QUOTES, 'UTF-8') ?></label><input class="otp" id="otp-code" type="text" inputmode="numeric" pattern="[0-9]{5}" maxlength="5" required><p class="message" id="otp-message"></p><button class="primary" id="verify" type="submit"><?= htmlspecialchars($lang['verify_otp'] ?? 'Verify code', ENT_QUOTES, 'UTF-8') ?></button></form><button class="resend" id="resend" type="button"><?= htmlspecialchars($lang['resend_otp'] ?? 'Resend code', ENT_QUOTES, 'UTF-8') ?></button><p class="message" id="resend-message"></p></section></div>
<div class="backdrop" id="password-modal" <?= $isVerified?'':'hidden' ?>><section class="modal-card" role="dialog" aria-modal="true"><button class="close" type="button" data-close>&times;</button><h2><?= htmlspecialchars($lang['reset_password'] ?? 'Reset password', ENT_QUOTES, 'UTF-8') ?></h2><p><?= htmlspecialchars($lang['new_password'] ?? 'Enter your new password.', ENT_QUOTES, 'UTF-8') ?></p><form id="password-form"><label for="new-password"><?= htmlspecialchars($lang['new_password'] ?? 'New password', ENT_QUOTES, 'UTF-8') ?></label><div class="password-wrap"><input id="new-password" type="password" minlength="6" required><button class="eye" type="button" data-target="new-password">&#128065;</button></div><label for="confirm-password"><?= htmlspecialchars($lang['confirm_password'] ?? 'Confirm password', ENT_QUOTES, 'UTF-8') ?></label><div class="password-wrap"><input id="confirm-password" type="password" minlength="6" required><button class="eye" type="button" data-target="confirm-password">&#128065;</button></div><p class="message" id="password-message"></p><button class="primary" id="reset" type="submit"><?= htmlspecialchars($lang['reset_password'] ?? 'Reset password', ENT_QUOTES, 'UTF-8') ?></button></form></section></div>
<script>
const endpoint='employerforgetpassword_process.php',otpModal=document.getElementById('otp-modal'),passwordModal=document.getElementById('password-modal'),resend=document.getElementById('resend');let timer;async function action(name,values){const response=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({action:name,...values})});return response.json()}function text(id,value){document.getElementById(id).textContent=value||''}function lockResend(){clearInterval(timer);let seconds=60;resend.disabled=true;text('resend-message',seconds);timer=setInterval(()=>{seconds--;text('resend-message',seconds>0?seconds:'');if(seconds<=0){clearInterval(timer);resend.disabled=false}},1000)}document.getElementById('otp-form').addEventListener('submit',async e=>{e.preventDefault();const button=document.getElementById('verify');button.disabled=true;try{const data=await action('verify_otp',{otp:document.getElementById('otp-code').value});text('otp-message',data.message);if(data.success){otpModal.hidden=true;passwordModal.hidden=false;document.getElementById('new-password').focus()}}catch(error){text('otp-message','<?= addslashes($lang['reset_generic_error'] ?? 'An error occurred. Please try again.') ?>')}button.disabled=false});resend.addEventListener('click',async()=>{resend.disabled=true;try{const data=await action('resend_otp',{});text('resend-message',data.message);if(data.success)lockResend();else resend.disabled=false}catch(error){resend.disabled=false}});document.getElementById('password-form').addEventListener('submit',async e=>{e.preventDefault();const button=document.getElementById('reset');button.disabled=true;try{const data=await action('reset_password',{new_password:document.getElementById('new-password').value,confirm_password:document.getElementById('confirm-password').value});text('password-message',data.message);if(data.success)setTimeout(()=>window.location.href='employerlogin.php',1200)}catch(error){text('password-message','<?= addslashes($lang['reset_generic_error'] ?? 'An error occurred. Please try again.') ?>')}button.disabled=false});document.querySelectorAll('[data-close]').forEach(button=>button.addEventListener('click',()=>window.location.href='employerforgetpassword.php'));document.querySelectorAll('.eye').forEach(button=>button.addEventListener('click',()=>{const input=document.getElementById(button.dataset.target);input.type=input.type==='password'?'text':'password'}));if(!passwordModal.hidden)document.getElementById('new-password').focus();else document.getElementById('otp-code').focus();
</script></body></html>
